  withThrowOnInvalid(true, () => {
    expect(() => Interval.fromISO("nonsense")).toThrow();
    expect(() => Interval.fromISO("foo/bar")).toThrow();
  });
});

test("Interval.fromISO returns an invalid Interval when Settings.throwOnInvalid is false", () => {
  withThrowOnInvalid(false, () => {
