    expect(() => Interval.fromISO("2007-03-01T13:00:00/P1Y2M10DT2H30M")).not.toThrow();
    expect(() => Interval.fromISO("P1Y2M10DT2H30M/2008-05-11T15:30:00")).not.toThrow();
