// ---- independent proleptic Gregorian reference (Howard Hinnant's algorithms) ----
function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}
function civilFromDays(z) {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365
  );
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { year: y + (m <= 2 ? 1 : 0), month: m, day: d };
}
function refPlusDays(y, m, d, n) {
  return civilFromDays(daysFromCivil(y, m, d) + n);
}

test("DateTime#plus works across the 100 barrier when passing through February", () => {
  // 0099-12-31 + 61 days passes through February of year 100 (not a leap year) -> 0100-03-02
  const d = DateTime.fromISO("0099-12-31", { zone: "utc" }).plus({ days: 61 });
  expect([d.year, d.month, d.day]).toEqual([100, 3, 2]);

  // explicit spot checks (values cross-checked with python datetime / GNU date)
  const cases = [
    ["0099-12-31", 2, [100, 1, 2]],
    ["0099-12-31", 59, [100, 2, 28]],
    ["0099-12-31", 60, [100, 3, 1]],
    ["0099-12-31", 61, [100, 3, 2]],
    ["0099-12-31", 90, [100, 3, 31]],
    ["0099-12-30", 62, [100, 3, 2]],
    ["0000-01-01", 59, [0, 2, 29]], // year 0 is a leap year
    ["0000-01-01", 60, [0, 3, 1]],
    ["0100-02-28", 1, [100, 3, 1]], // year 100 is NOT a leap year
    ["0400-02-28", 1, [400, 2, 29]], // year 400 IS a leap year (divisible by 400)
    ["1900-02-28", 1, [1900, 3, 1]],
    ["2100-02-28", 1, [2100, 3, 1]]
  ];
  for (const [iso, n, want] of cases) {
    const got = DateTime.fromISO(iso, { zone: "utc" }).plus({ days: n });
    expect([got.year, got.month, got.day]).toEqual(want);
  }
});

test("exhaustive: plus({days}) matches proleptic Gregorian reference for years 0..105", () => {
  const mismatches = [];
  for (let y = 0; y <= 105; y++) {
    for (const [m, d] of [[1, 1], [1, 31], [2, 28], [11, 30], [12, 30], [12, 31]]) {
      const iso = `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      const start = DateTime.fromISO(iso, { zone: "utc" });
      expect(start.isValid).toBe(true);
      for (let n = 1; n <= 400; n++) {
        const got = start.plus({ days: n });
        const want = refPlusDays(y, m, d, n);
        if (got.year !== want.year || got.month !== want.month || got.day !== want.day) {
          mismatches.push(`${iso}+${n}d got ${got.toISODate()} want ${want.year}-${want.month}-${want.day}`);
        }
      }
    }
  }
  console.log("mismatches:", mismatches.length);
  console.log(mismatches.slice(0, 20).join("\n"));
  expect(mismatches).toEqual([]);
});
