/* global test expect */
import { Duration } from "/luxon/src/luxon";

const units = [
  "years",
  "quarters",
  "months",
  "weeks",
  "days",
  "hours",
  "minutes",
  "seconds",
  "milliseconds"
];

// Plausible reconstruction of "Duration#normalize can convert all unit pairs":
// for every ordered pair of units, a 1-unit duration shifted/normalized into the
// other unit must be finite and must round-trip back to the original unit.
test("Duration#normalize can convert all unit pairs", () => {
  units.forEach(u => {
    units.forEach(l => {
      const dur = Duration.fromObject({ [u]: 1 });
      const shifted = dur.shiftTo(l);
      expect(shifted.isValid).toBe(true);
      expect(Number.isFinite(shifted.get(l))).toBe(true);

      // round trip back
      const back = shifted.shiftTo(u);
      expect(back.get(u)).toBeCloseTo(1, 8);

      // normalize of a two-unit duration must be finite and preserve the total
      const two = Duration.fromObject({ [u]: 1, [l]: 1 });
      const norm = two.normalize();
      expect(norm.isValid).toBe(true);
      Object.values(norm.toObject()).forEach(v => expect(Number.isFinite(v)).toBe(true));
      expect(norm.as("milliseconds")).toBeCloseTo(two.as("milliseconds"), 6);
    });
  });
});
EOF
